// TASK-0032 — REAL_ROOT in real WebView2. No simulated DOM, no alternate renderer,
// no personal data: the tree under test was generated by task0032-seed-proof.py.
import assert from "node:assert/strict";
import {writeFile, stat, readdir, readFile} from "node:fs/promises";
import {setTimeout as pause} from "node:timers/promises";
import {join, relative} from "node:path";
const port=Number(process.argv[2]); const variant=process.argv[3];
assert(/^task0032-[a-f0-9]+$/.test(variant));

// The seed arrives on stdin because it carries the absolute path this harness
// has to search for. It is never written to the artefact — TASK-0032 §6 asks
// for the verdict, not the sentinel.
const seed=JSON.parse(await new Promise((resolve,reject)=>{let text="";process.stdin.setEncoding("utf8");process.stdin.on("data",c=>{text+=c;});process.stdin.on("end",()=>resolve(text));process.stdin.on("error",reject);}));
const {brainId, sourceRef, sourceLabel, absolutePath, filesWritten}=seed;
const sourceRoot=join(".filetopo-sandbox",variant,"arbre-de-test");
const stateRoot=join(".filetopo-sandbox","variants",variant);
const indexFile=join(stateRoot,"brains",brainId,"map","index.sqlite");

let target;
for(let n=0;n<100;n++) {
  try {const pages=await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); target=pages.find(p=>p.type==="page"); if(target) break;} catch {}
  await pause(200);
}
assert(target,"WebView2 CDP page unavailable");
const ws=new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.addEventListener("open",resolve,{once:true});ws.addEventListener("error",reject,{once:true});});
let serial=0; const pending=new Map(); const fatal=[];
ws.addEventListener("message",({data})=>{const event=JSON.parse(data); if(event.id){const p=pending.get(event.id);pending.delete(event.id);if(event.error)p?.reject(new Error(JSON.stringify(event.error)));else p?.resolve(event.result);}else if(event.method==="Runtime.exceptionThrown" || event.method==="Log.entryAdded" && event.params.entry.level==="error") fatal.push(event);});
const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
async function evaluate(expression){const r=await send("Runtime.evaluate",{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text);return r.result.value;}
async function until(expression,limit=240000){const start=Date.now();while(Date.now()-start<limit){if(await evaluate(expression))return;await pause(100);}throw new Error(`timeout: ${expression}`);}
const invoke=(command,args={})=>evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
const refuse=(command,args={})=>evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)}).then(()=>null,e=>String(e))`);
await send("Runtime.enable");await send("Log.enable");

// --- the source, as it stands before FileTopo has ever looked at it ---------
async function inventory(root){
  const seen={};
  async function walk(at){
    for(const entry of (await readdir(at,{withFileTypes:true})).sort((a,b)=>a.name<b.name?-1:1)){
      const path=join(at,entry.name); const key=relative(root,path).split("\\").join("/");
      const info=await stat(path);
      seen[key]=entry.isDirectory()?{dir:true}:{size:info.size,mtimeMs:Math.trunc(info.mtimeMs)};
      if(entry.isDirectory()) await walk(path);
    }
  }
  await walk(root); return seen;
}
const before=await inventory(sourceRoot);
assert.equal(Object.keys(before).length,filesWritten+8,"the generated tree is what the seed says it is");

await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
await evaluate(`window.task0032Keys=[];document.addEventListener('keydown',e=>window.task0032Keys.push({key:e.key,trusted:e.isTrusted}),true)`);
async function key(k){
  const vk=k==="Enter"?13:0;
  await send("Input.dispatchKeyEvent",{type:"keyDown",key:k,code:k,windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk,...(k==="Enter"?{text:"\r",unmodifiedText:"\r"}:{})});
  await send("Input.dispatchKeyEvent",{type:"keyUp",key:k,code:k,windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk});await pause(120);
}
async function activate(selector){await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);await key("Enter");}

// --- the picker ships, and is not opened ------------------------------------
// A native modal cannot be driven from CDP without a fragile Win32 automation,
// which TASK-0032 §6 explicitly does not ask for. What the host proves is that
// the control is present, enabled and reachable; what the command *does* is
// proved by RR2 in Rust, against the same `register_real_root` it calls.
const picker=await evaluate(`(()=>{const b=document.querySelector('[data-testid="brain-add-real-root"]');return b?{present:true,disabled:b.disabled,label:b.textContent.trim()}:{present:false};})()`);
assert.equal(picker.present,true,"the Ajouter un dossier control must ship");
assert.equal(picker.disabled,false);

// --- the catalogue holds a REAL_ROOT, and no path -----------------------------
const catalog=await invoke("map_brains");
const record=catalog.brains.find(b=>b.brainId===brainId);
assert(record,"the seeded REAL_ROOT brain must be in the catalogue");
assert.equal(record.sourceKind,"REAL_ROOT");
assert.equal(record.sourceRef,sourceRef);
assert.equal(record.sourceLabel,sourceLabel);
assert.equal(catalog.activeBrainId,brainId);
assert.equal(catalog.schemaVersion,2);

// --- opening an unindexed real root reads nothing ---------------------------
const notBuilt=await refuse("map_open",{brainId});
assert.match(notBuilt,/map_not_built/);
assert.equal(await stat(indexFile).then(()=>true,()=>false),false,"map_open must not create an index");
assert.deepEqual(await inventory(sourceRoot),before,"map_open must not touch the source");
const indexedLabel=await evaluate(`document.querySelector('[data-testid="lifecycle-refresh"]').textContent.trim()`);
assert.equal(indexedLabel,"Indexer","an unindexed brain calls the action what it is");

// --- the first indexing, by a real keystroke --------------------------------
await activate('[data-testid="lifecycle-refresh"]');
await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled && document.querySelectorAll('[role="treeitem"]').length > 0`);
const build=await invoke("map_refresh",{brainId});
assert.equal(build.sourceKind,"REAL_ROOT");
assert.equal(build.sourceRef,sourceRef);
assert.equal(build.sourceLabel,sourceLabel);
assert.equal(build.sourceRead,true);
assert.equal(build.fingerprintBefore,null,"DEC-0033 F — a real root is not fingerprinted");
assert.equal(build.fingerprintAfter,null);
assert.equal(build.readOnlyConfirmed,false,"and does not claim to be confirmed by one");
assert.equal(build.plannedNodes,0,"a real tree has no frozen plan");
assert.equal(build.nodeCount,Object.keys(before).length+1,"root included");
assert.deepEqual(build.diagnostics,[]);

// --- open / refresh / rebuild, each by a real keystroke ----------------------
const actionEvidence={};
for (const action of ["open","refresh","rebuild"]) {
  const priorSource=await inventory(sourceRoot);
  const priorOpen=await invoke("map_open",{brainId});
  await activate(`[data-testid="lifecycle-${action}"]`);
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  const afterOpen=await invoke("map_open",{brainId});
  assert.equal(afterOpen.indexId,priorOpen.indexId);
  assert.equal(afterOpen.revision,priorOpen.revision+(action==="open"?0:1));
  assert.equal(afterOpen.sourceRead,false,"opening never reads the source");
  assert.equal(afterOpen.state,"OPENED_EXISTING");
  assert.deepEqual(await inventory(sourceRoot),priorSource,`${action} changed the source`);
  actionEvidence[action]={buttonActivatedByTrustedKey:true,beforeRevision:priorOpen.revision,afterRevision:afterOpen.revision,indexIdUnchanged:afterOpen.indexId===priorOpen.indexId,sourceUnchanged:true};
}
const refreshedLabel=await evaluate(`document.querySelector('[data-testid="lifecycle-refresh"]').textContent.trim()`);
assert.equal(refreshedLabel,"Actualiser","an indexed brain calls the same action what it now is");

// --- the bounded projection, unchanged --------------------------------------
const view=await invoke("map_view",{brainId});
const counts=await evaluate(`(()=>{const t=document.querySelector('.map-territory[data-brain-id=${JSON.stringify(brainId)}]');return {nodes:t.querySelectorAll('[role="treeitem"]').length,aggregates:t.querySelectorAll('[data-aggregate]').length,edges:t.querySelectorAll('.map-hierarchy-edge').length};})()`);
assert.equal(counts.nodes,view.materializedCount);
assert.equal(counts.aggregates,view.aggregates.length);
assert.equal(counts.edges,view.hierarchyEdges.length);
assert(counts.nodes+counts.aggregates<=view.viewBudget,"the projection must stay under its budget");
assert(view.nodeCount>view.materializedCount,"this tree is bigger than the budget, so bounding is really exercised");

// --- the source is untouched, and holds nothing of FileTopo's ---------------
const after=await inventory(sourceRoot);
assert.deepEqual(after,before,"refresh and rebuild must leave the source byte-identical");
const strays=Object.keys(after).filter(name=>/filetopo/i.test(name)||/\.sqlite(-wal|-shm)?$/i.test(name));
assert.deepEqual(strays,[],"FileTopo left an artefact under the analysed root");

// --- no absolute path anywhere the interface can see ------------------------
const detail=await invoke("map_node_detail",{reference:{brainId,nodeId:view.rootId}});
const payloads=[catalog,record,build,await invoke("map_open",{brainId}),view,detail,await invoke("map_host_info")];
const escaped=absolutePath.split("\\").join("\\\\");
let absolutePathLeak=false;
for (const payload of payloads) {
  const text=JSON.stringify(payload);
  if (text.includes(absolutePath) || text.includes(escaped)) absolutePathLeak=true;
}
// The index file itself: a derived artefact somebody could copy off the machine.
const indexBytes=await readFile(indexFile);
if (indexBytes.includes(Buffer.from(absolutePath,"utf16le")) || indexBytes.includes(Buffer.from(absolutePath,"utf8"))) absolutePathLeak=true;
// And the host log, which is where a careless `hostLog()` would have put it.
const hostLog=await readFile(join(".filetopo-sandbox",variant,"app.log"),"utf8").catch(()=>"");
if (hostLog.includes(absolutePath)) absolutePathLeak=true;
assert.equal(absolutePathLeak,false,"the absolute source path escaped the catalogue");

const screenshot=await send("Page.captureScreenshot",{format:"png"});
await writeFile(`.filetopo-sandbox/${variant}/projection.png`,Buffer.from(screenshot.data,"base64"));
const keys=await evaluate("window.task0032Keys");
assert(keys.length>0 && keys.every(k=>k.trusted),"every keystroke must be a real one");
assert.equal(fatal.length,0,"fatal page/console errors");

const host=await invoke("map_host_info");
const artifact={
  task:"TASK-0032",
  status:"NONCANONICAL_ENGINEERING_EVIDENCE",
  engine:"Windows Tauri / real WebView2",
  webviewVersion:host.webviewVersion,tauriVersion:host.tauriVersion,sqliteVersion:host.sqliteVersion,
  source:"REAL_ROOT registered internally -> explicit map_refresh -> read-only map_open -> bounded map_view -> MapApp/MapView",
  realRoot:{
    kind:record.sourceKind,
    generatedByTheProofNotByTheUser:true,
    personalDataUsed:false,
    entries:Object.keys(before).length,
    indexedNodes:build.nodeCount,
    labelIsAFolderNameNotAPath:record.sourceLabel===sourceLabel,
  },
  picker:{controlPresent:picker.present,enabled:!picker.disabled,nativeDialogueOpened:false,registrationProvedInRustByRR2:true},
  lifecycle:{notBuiltBeforeIndexing:true,indexCreatedOnlyByExplicitRefresh:true,openReadsIndexOnly:true,identityPreserved:true,revisionAdvancesOnlyOnPublication:true,actionEvidence,actionLabelBeforeIndexing:indexedLabel,actionLabelAfterIndexing:refreshedLabel},
  readOnly:{sourceByteIdenticalAfterRefreshAndRebuild:true,fingerprintTaken:false,filetopoArtifactsUnderRoot:strays.length},
  privacy:{absolutePathLeak,dtoPayloadsInspected:payloads.length,indexFileInspected:true,hostLogInspected:hostLog.length>0},
  boundedProjection:{indexed:view.nodeCount,materialized:view.materializedCount,nonMaterialized:view.nonMaterializedCount,aggregates:view.aggregates.length,budget:view.viewBudget,domNodes:counts.nodes,domAggregates:counts.aggregates,domMatchesProductPage:true},
  trustedKeydowns:keys.length,
  fatalConsoleErrors:fatal.length,
  limits:[
    "No personal brain: the analysed tree was generated by task0032-seed-proof.py and dies with the proof root",
    "The native folder dialogue is not automated; the control's presence is observed and its registration primitive is proved by RR2 in Rust",
    "The REAL_ROOT row is written by the seed, as TASK-0032 §7 allows, so the product path after internal registration is what this pass measures",
    "Development workstation; not a modest-laptop acceptance test, and no large-root performance claim",
    "No watcher, no incremental update, no FTS",
  ],
};
await writeFile("docs/performance/runs/TASK-0032-webview2.json",JSON.stringify(artifact,null,2)+"\n");
console.log(JSON.stringify(artifact));
ws.close();
